insert into jowwa_private.service_claim_registry(directory_id,snapshot,business_phones,evidence) values('directory-auc-daycare','{"id":"directory-auc-daycare","name":"حضانة الجامعة الأمريكية — EYC Day Care","category":"حضانات","address":"حرم الجامعة الأمريكية بالقاهرة الجديدة — Campus Center، Arnold Pavilion، PO29، خارج كيان","phone":"+201002789987","description":"مركز رعاية أطفال داخل حرم الجامعة، تديره Early Years Company. موقع الجامعة يذكر استقبال استفسارات الأسر من خارج الجامعة أيضًا. المواعيد المنشورة: الأحد–الخميس 8:15 ص إلى 4:30 م، وتتبع تقويم الجامعة.","source":"https://www.aucegypt.edu/ar/node/15811","website":"https://www.aucegypt.edu/ar/node/15811","email":"daycare@aucegypt.edu","applicationUrl":"https://www.aucegypt.edu/ar/node/15811","applicationLabel":"التفاصيل والتقديم على موقع الجامعة","status":"الزيارة والمقابلة بموعد مسبق. أكّد شروط الدخول والسن والأماكن والمصروفات مباشرة؛ لا يوجد حجز مؤكد من جوه.","schemaType":"ChildCare","area":"surrounding","checkedAt":"2026-11-04","url":"/place/directory-auc-daycare","image":"/social/directory-auc-daycare.png"}'::jsonb,array['+201002789987'],'[{"phone":"+201002789987","sourceUrl":"https://www.aucegypt.edu/ar/node/15811","sourceType":"reviewed_business_contact","basis":"official_business_website","checkedAt":"2026-11-04","reviewNote":"AUC official Day Care page names the independent EYC operator and this direct mobile contact; updated 2026-10-07."}]'::jsonb) on conflict(directory_id) do nothing;
